  {
  zRenameRank = (char const   *)"WITH Lzn(nlz) AS (  SELECT 0 AS nlz  UNION  SELECT nlz+1 AS nlz FROM Lzn  WHERE EXISTS(   SELECT 1   FROM ColNames t, ColNames o   WHERE    iif(t.name IN (SELECT * FROM RepeatedNames),     printf(\'%s_%s\',      t.name, substring(printf(\'%.*c%0.*d\',nlz+1,\'0\',$1,t.cpos),2)),     t.name    )    =    iif(o.name IN (SELECT * FROM RepeatedNames),     printf(\'%s_%s\',      o.name, substring(printf(\'%.*c%0.*d\',nlz+1,\'0\',$1,o.cpos),2)),     o.name    )    COLLATE NOCASE    AND o.cpos<>t.cpos   GROUP BY t.cpos  )) UPDATE Colnames AS t SET chop = 0, suff = iif(name IN (SELECT * FROM RepeatedNames),  printf(\'_%s\', substring(   printf(\'%.*c%0.*d\',(SELECT max(nlz) FROM Lzn)+1,\'0\',1,t.cpos),2)),  \'\' )";
  goto zRenameRank__INIT_INLINE_zRenameRank__INIT;
  }
  zRenameRank__INIT_INLINE_zRenameRank__INIT: /* CIL Label */ ;
